import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";
import type { ToolRecord } from "./src/core/context-pruning/types.ts";

const root = mkdtempSync(join(tmpdir(), "aide-dedup-regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "搜索结果 😀 café\\n".repeat(300);
const args = { query: "example" };
const full = (callId: string): ToolRecord => ({
  callId, toolName: "code_search", args, originalOutput: output,
  prunedOutput: null, timestamp: 0,
});
const run = (tracker: ContextPruningTracker, call: string) => tracker.process(
  call, "code_search", args, output,
