);

test("finalized outputs, retained originals and byte statistics survive reloading", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(third.output).toContain("callId: first");
  expect(second.recoveryPath).toBeDefined();
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory()[1].originalOutput).toBe(output);
  expect(tracker.getHistory()[1].prunedOutput).toBe(second.output);
  expect(tracker.getStats()).toEqual({
    totalCalls: 3, prunedCalls: 2,
    totalBytesSaved: 2 * Buffer.byteLength(output) - Buffer.byteLength(second.output) - Buffer.byteLength(third.output),
    estimatedContextBytes: Buffer.byteLength(output) + Buffer.byteLength(second.output) + Buffer.byteLength(third.output),
  });
  const reloaded = new ContextPruningTracker(root);
  reloaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(reloaded.getStats()).toEqual(tracker.getStats());
  expect(run(reloaded, "fourth").output).toContain("callId: first");
});

test("uses the newest full match and never a shortened matching output", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.loadHistory([full("old"), full("new"), {
    ...full("shortened"), originalOutput: output + "extra", prunedOutput: output,
  }]);
  expect(run(tracker, "next").output).toContain("callId: new");
});

test("emits a new full baseline after the original leaves retained history", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "one");
  expect(run(tracker, "two").modified).toBe(true);
  expect(run(tracker, "three").output).toContain("callId: one");
